// ============================================================
// Weekly KPI & Anomaly Detection (v3 - cleans text fields + robust week selection)
// Paste this into an n8n Code node connected after "Fetch Superstore Data"
// ============================================================

const rows = $input.all().map(item => item.json);

// --- Helper: convert an Order Date into a "Year-Week" key, e.g. "2016-W05" ---
function getWeekKey(dateStr) {
  const date = new Date(dateStr);
  const target = new Date(date.valueOf());
  const dayNr = (date.getDay() + 6) % 7;
  target.setDate(target.getDate() - dayNr + 3);
  const firstThursday = target.valueOf();
  target.setMonth(0, 1);
  if (target.getDay() !== 4) {
    target.setMonth(0, 1 + ((4 - target.getDay()) + 7) % 7);
  }
  const weekNumber = 1 + Math.ceil((firstThursday - target) / 604800000);
  return `${date.getFullYear()}-W${String(weekNumber).padStart(2, '0')}`;
}

// --- Step 1: Group every row by Region + Week (with cleaned text fields) ---
const weeklyData = {};

for (const row of rows) {
  // .trim() removes stray leading/trailing spaces that make "South" and "South " look different
  const region = (row['Region'] || '').toString().trim();
  const orderDate = row['Order Date'];
  const sales = parseFloat(row['Sales']) || 0;
  const customerId = (row['Customer ID'] || '').toString().trim();

  if (!region || !orderDate) continue;

  const weekKey = getWeekKey(orderDate);
  const groupKey = `${region}|${weekKey}`;

  if (!weeklyData[groupKey]) {
    weeklyData[groupKey] = {
      region,
      weekKey,
      totalSales: 0,
      customers: new Set(),
      orderCount: 0,
    };
  }

  weeklyData[groupKey].totalSales += sales;
  weeklyData[groupKey].customers.add(customerId);
  weeklyData[groupKey].orderCount += 1;
}

// --- Step 2: Flatten into one row per Region+Week ---
const weeklyArray = Object.values(weeklyData).map(w => ({
  region: w.region,
  weekKey: w.weekKey,
  totalSales: Math.round(w.totalSales * 100) / 100,
  uniqueCustomers: w.customers.size,
  orderCount: w.orderCount,
}));

const regions = [...new Set(weeklyArray.map(w => w.region))];
const allWeeksDesc = [...new Set(weeklyArray.map(w => w.weekKey))].sort().reverse();

// --- Step 3: Score recent weeks by region coverage, pick the best one ---
const weekScores = allWeeksDesc.map(wk => {
  const weekRows = weeklyArray.filter(w => w.weekKey === wk);
  const regionsPresent = new Set(weekRows.map(w => w.region));
  const totalOrders = weekRows.reduce((sum, w) => sum + w.orderCount, 0);
  return { wk, regionCount: regionsPresent.size, totalOrders };
});

let currentWeek;
const fullCoverage = weekScores.find(s => s.regionCount === regions.length);
if (fullCoverage) {
  currentWeek = fullCoverage.wk;
} else {
  const candidates = [...weekScores.slice(0, 10)].sort(
    (a, b) => b.regionCount - a.regionCount || b.totalOrders - a.totalOrders
  );
  currentWeek = candidates[0] ? candidates[0].wk : allWeeksDesc[0];
}

// --- Step 4: For each Region, compare current week vs trailing baseline ---
const results = [];

for (const region of regions) {
  const regionWeeks = weeklyArray
    .filter(w => w.region === region)
    .sort((a, b) => a.weekKey.localeCompare(b.weekKey));

  const currentWeekData = regionWeeks.find(w => w.weekKey === currentWeek);
  if (!currentWeekData) continue;

  const baselineWeeks = regionWeeks.filter(w => w.weekKey < currentWeek).slice(-8);

  if (baselineWeeks.length < 3) {
    results.push({
      region,
      weekKey: currentWeek,
      totalSales: currentWeekData.totalSales,
      uniqueCustomers: currentWeekData.uniqueCustomers,
      orderCount: currentWeekData.orderCount,
      baselineMean: null,
      zScore: null,
      isAnomaly: false,
      note: 'Not enough historical weeks yet for this region',
    });
    continue;
  }

  const baselineSales = baselineWeeks.map(w => w.totalSales);
  const mean = baselineSales.reduce((a, b) => a + b, 0) / baselineSales.length;
  const variance = baselineSales.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / baselineSales.length;
  const stdDev = Math.sqrt(variance);

  const zScore = stdDev === 0 ? 0 : (currentWeekData.totalSales - mean) / stdDev;
  const isAnomaly = Math.abs(zScore) > 2;

  results.push({
    region,
    weekKey: currentWeek,
    totalSales: currentWeekData.totalSales,
    uniqueCustomers: currentWeekData.uniqueCustomers,
    orderCount: currentWeekData.orderCount,
    baselineMean: Math.round(mean * 100) / 100,
    zScore: Math.round(zScore * 100) / 100,
    isAnomaly,
  });
}

return results.map(r => ({ json: r }));

// ============================================================
// Format Data For AI
// Combines the 4 region rows into one clean text block for the Gemini prompt
// ============================================================

const items = $input.all().map(item => item.json);

const weekLabel = items[0] ? items[0].weekKey : 'this week';

const summaryLines = items.map(r => {
  const anomalyFlag = r.isAnomaly ? ' [ANOMALY FLAGGED]' : '';
  const baseline = (r.baselineMean !== null && r.baselineMean !== undefined)
    ? `$${r.baselineMean}`
    : 'N/A (not enough history)';
  const z = (r.zScore !== null && r.zScore !== undefined) ? r.zScore : 'N/A';

  return `- ${r.region}: Sales $${r.totalSales}, Unique Customers ${r.uniqueCustomers}, Orders ${r.orderCount}, Baseline Avg Sales ${baseline}, Z-Score ${z}${anomalyFlag}`;
}).join('\n');

const reportData = `Week: ${weekLabel}\n\nRegional Performance:\n${summaryLines}`;

return [{ json: { weekLabel, reportData, regions: items } }];

// ============================================================
// Build Email & Chart
// Combines Gemini's summary text with a QuickChart bar chart into final HTML
// ============================================================

// Gemini's generated summary text (from the node right before this one)
   const summaryText = $json.content.parts[0].text || 'Summary unavailable';

// Pull the raw per-region numbers from the earlier "Format Data For AI" node
const regions = $('Format Data For AI').item.json.regions;
const weekLabel = $('Format Data For AI').item.json.weekLabel;

// Build a QuickChart.io bar chart config - red bars for flagged anomalies
const chartConfig = {
  type: 'bar',
  data: {
    labels: regions.map(r => r.region),
    datasets: [{
      label: 'Sales ($)',
      data: regions.map(r => r.totalSales),
      backgroundColor: regions.map(r => (r.isAnomaly ? '#e74c3c' : '#3498db'))
    }]
  },
  options: {
    plugins: {
      title: { display: true, text: `Regional Sales - Week ${weekLabel}` }
    }
  }
};

const chartUrl = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify(chartConfig))}`;

// Build the final HTML email body
const html = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: auto;">
  <h2 style="color:#2c3e50;">Weekly MIS Report - ${weekLabel}</h2>
  <img src="${chartUrl}" alt="Regional Sales Chart" style="width:100%; max-width:600px;" />
  <div style="white-space: pre-line; line-height:1.5; color:#34495e; margin-top:20px;">
${summaryText}
  </div>
  <p style="font-size:12px; color:#999; margin-top:30px;">Automated report generated by n8n + Gemini AI</p>
</div>
`;

   const anomalyCount = regions.filter(r => r.isAnomaly).length;
   return [{ json: { html, weekLabel, chartUrl, summaryText, anomalyCount } }];
